const dialog=document.querySelector('.image-dialog');let trigger;document.querySelectorAll('.zoom-image').forEach(button=>button.addEventListener('click',()=>{trigger=button;dialog.querySelector('img').src=button.dataset.image;dialog.querySelector('img').alt=button.dataset.caption;dialog.querySelector('p').textContent=button.dataset.caption;dialog.showModal()}));dialog.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});dialog.addEventListener('close',()=>trigger?.focus());